laBomMain_isUsed","readonly":false,"layRec":"isUsed","modelCode":"RM_1.0.0_formulaBOM_FormulaBomMain","namekey":"RM.formulaBOM.FormulaBomMain.isUsed","showType":"SELECT","exp":"equal","key":"isUsed","entityCode":"RM_1.0.0_formulaBOM","showFormat":"SELECT","iscrosscompany":false,"caseSensitive":false,"mnecode":false,"selfType":"BOOLEAN","columnType":"BOOLEAN","isrefselect":false,"name":"isUsed","modelcode":"RM_1.0.0_formulaBOM_FormulaBomMain","multable":false,"maxLength":null,"columnName":"IS_USED"}}],"expandType":"all","isExpandAll":true,"type":"layoutSearchWidget","layoutName":"layoutSearchWidget"},{"isSuperTable":false,"idPrefix":"ec_RM_formulaBOM_formulaBomMain_formulaBomList","isFirstLoad":false,"type":"layoutDatagrid","ptPageInit":"// 样式修改不可使用JQuery,需要使用平台提供的方法\nlet bomDataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''RM_1.0.0_formulaBOM_formulaBomList_formulaBomMain_sdg'');\nbomDataGrid.setBtnImg(''btn-copy'', ''sup-btn-own-copy'');\nbomDataGrid.setBtnImg(''btn-isUsed'', ''sup-btn-own-qiyong'');\nbomDataGrid.setBtnImg(''btn-isDisable'', ''sup-btn-own-ty'');\n// 设置单击事件\nbomDataGrid.setClickEvt(function (event, bom) {\n    console.log(''bomClick'')\n    let isUsed = bom.isUsed;\n    if (isUsed) {\n        setBtnStyle(''btn-update'', false);\n        setBtnStyle(''btn-isUsed'', false);\n        setBtnStyle(''btn-isDisable'', true);\n    } else {\n        setBtnStyle(''btn-update'', true);\n        setBtnStyle(''btn-isUsed'', true);\n        setBtnStyle(''btn-isDisable'', false);\n    }\n});","ratio_h":100,"dbcustomtextarea":"function bomDbClick(event,bom){\n    console.log(''bomDbClick'')\n    var isUsed=bom.isUsed;\n    var bomId=bom.id;\n    var url;\n    if(!isUsed){\n        url=''/msService/RM/formulaBOM/formulaBomMain/formulaBomEdit?id=''+bomId+''&viewCode=RM_1.0.0_formulaBOM_formulaBomList&entityCode=RM_1.0.0_formulaBOM&__pc__=Zm9ybXVsYUJvbUxpc3RfdXBkYXRlX21vZGlmeV9STV8xLjAuMF9mb3JtdWxhQk9NX2Zvcm11bGFCb21MaXN0fA__&openType=frame&viewType=edit'';\n    }else{\n        url=''/msService/RM/formulaBOM/formulaBomMain/formulaBomUsedView?id=''+bomId+''&viewCode=RM_1.0.0_formulaBOM_formulaBomList&entityCode=RM_1.0.0_formulaBOM&__pc__=Zm9ybXVsYUJvbUxpc3RfdXBkYXRlX21vZGlmeV9STV8xLjAuMF9mb3JtdWxhQk9NX2Zvcm11bGFCb21MaXN0fA__&openType=frame&viewType=edit'';\n    }\n    window.open(url);\n}","ptPageInit_es5":"// 样式修改不可使用JQuery,需要使用平台提供的方法\nvar bomDataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''RM_1.0.0_formulaBOM_formulaBomList_formulaBomMain_sdg'');\nbomDataGrid.setBtnImg(''btn-copy'', ''sup-btn-own-copy'');\nbomDataGrid.setBtnImg(''btn-isUsed'', ''sup-btn-own-qiyong'');\nbomDataGrid.setBtnImg(''btn-isDisable'', ''sup-btn-own-ty'');\n// 设置单击事件\nbomDataGrid.setClickEvt(function (event, bom) {\n    console.log(''bomClick'');\n    var isUsed = bom.isUsed;\n    if (isUsed) {\n        setBtnStyle(''btn-update'', false);\n        setBtnStyle(''btn-isUsed'', false);\n        setBtnStyle(''btn-isDisable'', true);\n    } else {\n        setBtnStyle(''btn-update'', true);\n        setBtnStyle(''btn-isUsed'', true);\n        setBtnStyle(''btn-isDisable'', false);\n    }\n});","isdbcustom":true,"modelCode":"RM_1.0.0_formulaBOM_FormulaBomMain","downloadXls":"/msService/RM/formulaBOM/formulaBomMain/downloadXls","selectFirstRow":false,"renderOver":"setTimeout(function () {\n\tlet data = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formulaBOM_formulaBomList_formulaBomMain_sdg\").getDatagridData();\n\tlet materialId = [];\n\tlet id;\n\tfor (let i = 0; i < data.length; i++) {\n\t\t\tif (data[i].productId != null && data[i].productId.id != null) {\n\t\t\t\t\tmaterialId.push({ \"materialId\": data[i].productId.id });\n\t\t\t}\n\t\t\telse\n\t\t\t\t\tmaterialId.push({ \"materialId\": -1 });\n\t}\n\t//if(data[i].materialId!=null&&data[i].materialId.id!=null){//如果物料编码字段不为空，则发送请求\n\tReactAPI.request({\n\t\t\ttype: \"post\",\n\t\t\turl: \"/msService/RM/formulaBOM/formulaBomMain/GetMaterialAttributes\",\n\t\t\tcontentType: \"application/json;charset=UTF-8\",\n\t\t\tdata: JSON.stringify(materialId)// 将json数据转化为字符\n\t}, function (res) {\n\t\t\tif (res.code==200) {\n\t\t\t\t\tfor (let i = 0; i < data.length; i++) {//遍历\n\t\t\t\t\t\t\tif (res.data[i] != null && res.data[i] == true) {//如果是危化品则为红色\n\t\t\t\t\t\t\t\t\tReactAPI.getComponentAPI(\"SupDataGrid\")\n\t\t\t\t\t\t\t\t\t\t\t.APIs(\"RM_1.0.0_formulaBOM_formulaBomList_formulaBomMain_sdg\")\n\t\t\t\t\t\t\t\t\t\t\t.setDatagridCellAttr(i, \"productId.code\", { style: { color: \"#B30303\" } });\n\t\t\t\t\t\t\t\t\t// console.log(\"i=\"+i+\",res.data=\"+res.data[i]);\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\telse if (res.data[i] != null && res.data[i] == false) {\n\t\t\t\t\t\t\t\t\tReactAPI.getComponentAPI(\"SupDataGrid\")\n\t\t\t\t\t\t\t\t\t\t\t.APIs(\"RM_1.0.0_formulaBOM_formulaBomList_formulaBomMain_sdg\")\n\t\t\t\t\t\t\t\t\t\t\t.setDatagridCellAttr(i, \"productId.code\", { style: { color: \"#505050\" } });\n\t\t\t\t\t\t\t\t\t// console.log(\"i=\"+i+\",res.data=\"+res.data[i]);\n\t\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t}\n\t}\n\t);\n\n}, 10);","buttons":[{"isSignatureConfig":true,"buttonstyle":"add","iscustomfunc":false,"useInMore":false,"viewselect":{"code":"RM_1.0.0_formulaBOM_formulaBomEdit","iscrosscompany":"false","name":"formulaBomEdit","title":"RM.viewtitle.randon1573460181835","mneType":"other","url":"/msService/RM/formulaBOM/formulaBomMain/formulaBomEdit","openType":"frame"},"isPublished":true,"ispermission":true,"cellCode":"cell_1573460872980_9657","buttonoperationcode":"formulaBomList_add_add_RM_1.0.0_formulaBOM_formulaBomList","isHide":false,"showname":"新增","ecEnv":"product","pc":"__pc__=Zm9ybXVsYUJvbUxpc3RfYWRkX2FkZF9STV8xLjAuMF9mb3JtdWxhQk9NX2Zvcm11bGFCb21MaXN0fA__","regionType":"BUTTON","iscallback":true,"modelCode":"RM_1.0.0_formulaBOM_FormulaBomMain","namekey":"RM.buttonPropertyshowName.randon1573461052496.flag","id":"add","operatetype":"ADD","isconfirm":false,"CODE":"formulaBomList_add_add_RM_1.0.0_formulaBOM_formulaBomList","NAME":"新增