e\n        materialId.push({ \"materialId\": -1 });\n}\nif (data.length != 0 && materialId.length != 0) {//如果物料编码字段不为空，则发送请求\n    ReactAPI.request({\n        type: \"post\",\n        url: \"/msService/RM/formulaBOM/formulaBomMain/GetMaterialAttributes\",\n        contentType: \"application/json;charset=UTF-8\",\n        data: JSON.stringify(materialId)// 将json数据转化为字符\n    }, function (res) {\n        if (res.code==200) {\n            for (let i = 0; i < data.length; i++) {//遍历\n                if (res.data[i] != null && res.data[i] == true) {//如果是危化品则为红色\n                    ReactAPI.getComponentAPI(\"SupDataGrid\")\n                        .APIs(\"RM_1.0.0_formulaBOM_formulaBomEditdg1573460506416\")\n                        .setDatagridCellAttr(i, \"material.code\", { style: { color: \"#B30303\" } });\n                    // console.log(\"i=\"+i+\",res.data=\"+res.data[i]);\n                }\n                else if (res.data[i] != null && res.data[i] == false) {\n                    ReactAPI.getComponentAPI(\"SupDataGrid\")\n                        .APIs(\"RM_1.0.0_formulaBOM_formulaBomEditdg1573460506416\")\n                        .setDatagridCellAttr(i, \"material.code\", { style: { color: \"#505050\" } });\n                    // console.log(\"i=\"+i+\",res.data=\"+res.data[i]);\n                }\n            }\n        }\n    }\n    );\n}","isEasyTable":false,"firstTd":1,"officeNotNull":false,"copyColumn":false,"cellCode":"cell_1573460513984_5848","isTransCondition":false,"nodeExpanded":false,"importExcel":false,"isOfficeSign":false,"columnType":"DATAGRID","isTitle":true,"dataGridName":"dg1573460506416","hasFastQuery":false,"fields":[{"callbackbody":"function callbackPosition(obj){\n    //发出一个请求，根据物料编码查找物料属性，返回物料属性的值，如果物料属性的值为危化品，则将单元格的物料编码字段设置为红色，其他情况不做处理\n        console.log(obj);\n        debugger\n        let data=ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formulaBOM_formulaBomEditdg1573460506416\");\n        let datarows = data.getSelect