tion (data, event) {\n                    callback(data, event);\n                }\n            },\n            {\n                text: ReactAPI.international.getText(''Button.text.cancel''), // 取消\n                onClick: event => {\n                    ReactAPI.destroyDialog(\"newDialog\");\n                }\n            }\n        ],\n        callback: (data, event) => {\n            callback(data, event);\n        },\n        onOk: (data, event) => {\n            callback(data, event);\n            // 添加成功\n            ReactAPI.showMessage(''s'', ReactAPI.international.getText(''WOM.custom.randon1586564469987''));\n        },\n        onCancel: (data, event) => {\n            ReactAPI.destroyDialog(dialogName);\n        }\n    });\n    var callback = (data, event) => {\n        //获取选择的指令，将数据填入表体\n        if (data.length > 0) {\n            var records = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formulaBOM_formulaBomEditdg1573460506416\").getDatagridData().map(record => Number(record.material.id));\n            var newrecords\n            if (records.length > 0) {\n                newrecords = data.filter(record => records.indexOf(record.id) == -1)\n            } else {\n                newrecords = data;\n            }\n            for (var i = 0; i < newrecords.length; i++) {\n                ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''RM_1.0.0_formulaBOM_formulaBomEditdg1573460506416'').addLine();\n                var length = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''RM_1.0.0_formulaBOM_formulaBomEditdg1573460506416'').getDatagridData().length - 1;\n                //产品\n                ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''RM_1.0.0_formulaBOM_formulaBomEditdg1573460506416'').setRowData(length, { material: newrecords[i] })\n            }\n            // 添加成功\n            ReactAPI.showMessage(''s'', ReactAPI.international.getText(''WOM.custom.randon1586564469987''));\n        } else {\n            //报错提示信息\n            ReactAPI.showMessage(\"f\", ReactAPI.international.getText(''WOM.custom.randon1594371176476''));\n        }\n    }\n}","funcname":"onclick=''taskRefClick(event)''","buttonstyle":"add","iscustomfunc":false,"useInMore":false,"isPublished":false,"ispermission":false,"cellCode":"cell_1617086180553_7527","isHide":false,"showname":"参照","pc":"__pc__=Uk1fMS4wLjBfZm9ybXVsYUJPTV9mb3JtdWxhQm9tRWRpdF9zZWxmfA__","regionType":"BUTTON","iscallback":false,"namekey":"RM.buttonPropertyshowName.randon1617086196669.flag","funcbody_es5":"function taskRefClick(event) {\n    ReactAPI.createDialog(\"newDialog\", {\n        title: ReactAPI.international.getText(''RM.custom.random1617758873313''), // 物料参照\n        size: 5,\n        url: \"/msService/BaseSet/material/material/materialRefLayout\",\n        isRef: true, //是否开启参照\n        buttons: [{\n            text: ReactAPI.international.getText(''Button.text.select''), // 选择\n            type: \"primary\",\n            onClick: function onClick(data, event) {\n                _callback(data, event);\n            }\n        }, {\n            text: ReactAPI.international.getText(''Button.text.cancel''), // 取消\n            onClick: function onClick(event) {\n                ReactAPI.destroyDialog(\"newDialog\");\n            }\n        }],\n        callback: function callback(data, event) {\n            _callback(data, event);\n        },\n        onOk: function onOk(data, event) {\n            _callback(data, event);\n            // 添加成功\n            ReactAPI.showMessage(''s'', ReactAPI.international.getText(''WOM.custom.randon1586564469987''));\n        },\n        onCancel: function onCancel(data, event) {\n            ReactAPI.destroyDialog(dialogName);\n        }\n    });\n    var _callback = function _callback(data, event) {\n        //获取选择的指令，将数据填入表体\n        if (data.length > 0) {\n            var records = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formulaBOM_formulaBomEditdg1573460506416\").getDatagridData().map(function (record) {\n                return Number(record.material.id);\n            });\n            var newrecords;\n            if (records.length > 0) {\n                newrecords = data.filter(function (record) {\n                    return records.indexOf(record.id) == -1;\n                });\n            } else {\n                newrecords = data;\n            }\n            for (var i = 0; i < newrecords.length; i++) {\n                ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''RM_1.0.0_formulaBOM_formulaBomEditdg1573460506416'').addLine();\n                var length = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''RM_1.0.0_formulaBOM_formulaBomEditdg1573460506416'').getDatagridData().length - 1;\n                //产品\n                ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''RM_1.0.0_formulaBOM_formulaBomEditdg1573460506416'').setRowData(length, { material: newrecords[i] });\n            }\n            // 添加成功\n            ReactAPI.showMessage(''s'', ReactAPI.international.getText(''WOM.custom.randon1586564469987''));\n        } else {\n            //报错提示信息\n            ReactAPI.showMessage(\"f\", ReactAPI.international.getText(''WOM.custom.randon1594371176476''));\n        }\n    };\n}","id":"ref","operatetype":"CUSTOM","isconfirm":false},{"confirmcontent":"SupDatagrid.button.delete","isSignatureConfig":true,"buttonstyle":"del","iscustomfunc":false,"useInMore":false,"isPublished":false,"ispermission":false,"cellCode":"cell_1573460618914_2804","isHide":false,"showname":"删行","pc":"__pc__=Uk1fMS4wLjBfZm9ybXVsYUJPTV9mb3JtdWxhQm9tRWRpdF9zZWxmfA__","regionType":"BUTTON","iscallback":false,"namekey":"RM.buttonPropertyshowName.radion1573460618914.flag","id":"delete","operatetype":"DELETEROW","isconfirm":true}],"autoresize":false,"DataGridCode":"RM_1.0.0_formulaBOM_formulaBomEditdg1573460506416","listPT":false,"renderOver_es5":"var dataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''RM_1.0.0_formulaBOM_formulaBomEditdg1573460506416'');\nvar data = dataGrid.getDatagridData();\nvar _iteratorNormalCompletion = true;\nvar _didIteratorError = false;\nvar _iteratorError = undefined;\n\ntry {\n    for (var _iterator = data[Symbol.iterator](), _step; !(_iteratorNormalCompletion = (_step = _iterator.next()).done); _iteratorNormalCompletion = true) {\n        var item = _step.value;\n\n        var isFixedQuantity = item.isFixedQuantity;\n        if (isFixedQuantity) {\n            dataGrid.setDatagridCellAttr(item.rowIndex, \"fixedQuantity\", { readonly: false });\n        } else {\n            dataGrid.setDatagridCellAttr(item.rowIndex, \"fixedQuantity\", { readonly: true });\n        }\n    }\n    //判断物料是否为危化品\n} catch (err) {\n    _didIteratorError = true;\n    _iteratorError = err;\n} finally {\n    try {\n        if (!_iteratorNormalCompletion && _iterator.return) {\n            _iterator.return();\n        }\n    } finally {\n        if (_didIteratorError) {\n            throw _iteratorError;\n        }\n    }\n}\n\nvar materialId = [];\nvar id = void 0;\nfor (var i = 0; i < data.length; i++) {\n    if (data[i].material != null && data[i].material.id != null) {\n        materialId.push({ \"materialId\": data[i].material.id });\n    } else materialId.push({ \"materialId\": -1 });\n}\nif (data.length != 0 && materialId.length != 0) {\n    //如果物料编码字段不为空，则发送请求\n    ReactAPI.request({\n        type: \"post\",\n        url: \"/msService/RM/formulaBOM/formulaBomMain/GetMaterialAttributes\",\n        contentType: \"application/json;charset=UTF-8\",\n        data: JSON.stringify(materialId) // 将json数据转化为字符\n    }, function (res) {\n        if (res.code == 200) {\n            for (var _i = 0; _i < data.length; _i++) {\n                //遍历\n                if (res.data[_i] != null && res.data[_i] == true) {\n                    //如果是危化品则为红色\n                    ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formulaBOM_formulaBomEditdg1573460506416\").setDatagridCellAttr(_i, \"material.code\", { style: { color: \"#B30303\" } });\n                    // console.log(\"i=\"+i+\",res.data=\"+res.data[i]);\n                } else if (res.data[_i] != null && res.data[_i] == false) {\n                    ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formulaBOM_formulaBomEditdg1573460506416\").setDatagridCellAttr(_i, \"material.code\", { style: { color: \"#505050\" } });\n                    // console.log(\"i=\"+i+\",res.data=\"+res.data[i]);\n                }\n            }\n        }\n    });\n}","copyRow":false,"queryUrl":null,"saveTemplate":false,"pendingDeal":false,"isTreeView":false,"openEmptyDoc":true,"multable":false}],"regionType":"DATAGRID","colwidth":"13,20,13,20,13,20","cssstyle":null,"customSection":null,"colNum":6,"name":null,"sectionCode":null,"refcol":"<tr style=''border:none;height:0px; ''><td style=''height:0px;border:none;width:13%''></td><td style=''height:0px;border:none;width:20%''></td><td style=''height:0px;border:none;width:13%''></td><td style=''height:0px;border:none;width:20%''></td><td style=''height:0px;border:none;width:13%''></td><td style=''height:0px;border:none;width:20%''></td></tr>","type":"layoutSection"}],"isrightbottomfixed":false,"layoutContent":"datagrid","type":"layout","ranksType":"panel","isShow":true,"isreadonlyBak":0,"parlayoutname":"tabs-1","ratio_h":75,"layoutmethod":"container","ptRealTimeLoad":1,"isreadonly":0,"layno":2,"layoutname":"column-3","islefttopfixed":false,"nums":1}],"tabViewIndex":0,"isborder":0,"isrightbottomfixed":false,"type":"layout","isreadonlyBak":0,"ptRealTimeLoad":1,"layoutmethod":"column","namekey":"ec.view.commoninfo","name":"常规信息","isreadonly":0,"layno":1,"id":null,"tabCode":"tab_0","layoutname":"tabs-1","nums":2,"islefttopfixed":false}],"layoutmethod":"tab","type":"layout"}],"layoutmethod":"column","type":"layout"}],"enableSimpleDealInfo":false,"title":"RM.viewtitle.randon1573460181835","url":"/msService/RM/formulaBOM/formulaBomMain/formulaBomEdit","dealInfoShow":false,"hasAttachment":true,"pageType":"EDIT","dealInfoGroup":"byTime","refCopy":{"isReference":false},"colNum":4,"layoutType":"classic","selfAdaption":false,"events":[{"function":"//批控地址\nlet batchServerId = ReactAPI.getComponentAPI(\"Reference\").APIs(''formulaBomMain.batchServerId.code'');\n\n//表体\nlet dataGrid = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formulaBOM_formulaBomEditdg1573460506416\");\nlet data = dataGrid.getDatagridData();\nif (!data.length) {\n    ReactAPI.showMessage(\"f\", ReactAPI.international.getText(\"RM.custom.randon1577173722465\"));\n    return false;\n}\nlet errorMessage = '''';\nlet set = new Set();\nfor (let item of data) {\n    let material = item.material;\n    if (!material) {\n        errorMessage += ReactAPI.international.getText(\"RM.custom.randon1578034607122\", item.rowIndex + 1) + ''<br>'';\n        continue;\n    }\n    let materialCode = item.material.code;\n    let putOrder = item.putSort;\n    let key = putOrder ? materialCode + putOrder : materialCode;\n    if (set.has(key)) {\n        errorMessage += ReactAPI.international.getText(\"RM.custom.randon1587964682895\", item.rowIndex + 1);\n    } else {\n        set.add(key);\n    }\n\n    //如果批控地址有值，表体标识字段不能为空\n    if (batchServerId.getValue().length > 0 && (item.putSort == '''' || item.putSort == null)) {\n        errorMessage += ReactAPI.international.getText(\"RM.custom.randon1587966610059\", item.rowIndex + 1);\n        //       ReactAPI.international.getText(\"EditView.notice.processing\")\n    }\n}\n\nif (errorMessage) {\n    ReactAPI.showMessage(\"f\", errorMessage);\n    return false;\n}","name":"onsave"},{"function":"// 当前表单的id存在且 [批控地址] 不为空时将 [批控地址] 置为只读\nvar formulaBomId = ReactAPI.getFormData().id;\nvar batchServerIds = ReactAPI.getComponentAPI(''Reference'').APIs(''formulaBomMain.batchServerId.code'').getValue();\nif (formulaBomId && batchServerIds.length) {\n    ReactAPI.getComponentAPI(''Reference'').APIs(''formulaBomMain.batchServerId.code'').setReadonly(true);\n}\n//判断