wspan":1,"cellCode":"cell_1589183609748_5050","element":{"showTypeHasChanged":true,"onlyLeaf":false,"code":"RM_1.0.0_formula_commonFormulaList_FASTQUERY_OTHER_RM_1.0.0_formula_Formula_batchContral","nullable":true,"containLower":false,"showFormatHasChanged":true,"partDepend":"common","defaultValueHasChanged":true,"dbColumnType":"BOOLEAN","crosscol":false,"ecEnv":"product","propertyCode":"RM_1.0.0_formula_Formula_batchContral","readonly":false,"layRec":"batchContral","modelCode":"RM_1.0.0_formula_Formula","namekey":"RM.formula.Formula.batchContral","showType":"SELECT","exp":"equal","key":"batchContral","entityCode":"RM_1.0.0_formula","showFormat":"SELECT","iscrosscompany":false,"caseSensitive":false,"mnecode":false,"selfType":"BOOLEAN","columnType":"BOOLEAN","isrefselect":false,"name":"batchContral","modelcode":"RM_1.0.0_formula_Formula","multable":false,"maxLength":null,"columnName":"BATCH_CONTRAL"}},{"colspan":1,"pc":"__pc__=Uk1fMS4wLjBfZm9ybXVsYV9jb21tb25Gb3JtdWxhTGlzdF9zZWxmfA__","regionType":"FASTQUERY","rowspan":1,"cellCode":"cell_1597134573748_7138","element":{"showTypeHasChanged":false,"onlyLeaf":false,"code":"RM_1.0.0_formula_commonFormulaList_FASTQUERY_OTHER_RM_1.0.0_formula_Formula_inspectTimer","nullable":true,"containLower":false,"showFormatHasChanged":false,"partDepend":"common","defaultValueHasChanged":false,"dbColumnType":"SYSTEMCODE","crosscol":false,"ecEnv":"product","propertyCode":"RM_1.0.0_formula_Formula_inspectTimer","readonly":false,"layRec":"inspectTimer","modelCode":"RM_1.0.0_formula_Formula","namekey":"RM.formula.Formula.inspectTimer","showType":"SELECTCOMP","exp":"equal","key":"inspectTimer","entityCode":"RM_1.0.0_formula","showFormat":"SELECTCOMP","iscrosscompany":false,"caseSensitive":false,"mnecode":false,"selfType":"SYSTEMCODE","fill":{"fillType":3,"fillName":"系统编码","fillContent":"RM_inspectTimer","listType":"list"},"columnType":"SYSTEMCODE","isrefselect":false,"name":"inspectTimer","modelcode":"RM_1.0.0_formula_Formula","multable":false,"maxLength":4000,"columnName":"INSPECT_TIMER"}}],"expandType":"all","isExpandAll":true,"type":"layoutSearchWidget","layoutName":"layoutSearchWidget"},{"isSuperTable":false,"idPrefix":"ec_RM_formula_formula_commonFormulaList","isFirstLoad":false,"type":"layoutDatagrid","ptPageInit":"// 样式修改不可使用JQuery,需要使用平台提供的方法\nlet sdg = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''RM_1.0.0_formula_commonFormulaList_formula_sdg'');\nsdg.setBtnImg(''btn-copy'', ''sup-btn-own-copy'');\nsdg.setBtnImg(''btn-start'', ''sup-btn-own-qiyong'');\nsdg.setBtnImg(''btn-end'', ''sup-btn-own-ty'');\nsdg.setBtnImg(''btn-default'', ''sup-btn-own-szmr'');\nsdg.setBtnImg(''btn-changeUse'', ''sup-btn-own-bgyt'');\nsdg.setBtnImg(''btn-suitline'', ''sup-btn-own-sz'');\nsdg.setBtnImg(''btn-checkDepartSet'', ''sup-btn-own-fqqj'');\nsdg.setBtnImg(''btn-proItemSet'', ''sup-btn-own-cdsz'');","ratio_h":100,"ptPageInit_es5":"// 样式修改不可使用JQuery,需要使用平台提供的方法\nvar sdg = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''RM_1.0.0_formula_commonFormulaList_formula_sdg'');\nsdg.setBtnImg(''btn-copy'', ''sup-btn-own-copy'');\nsdg.setBtnImg(''btn-start'', ''sup-btn-own-qiyong'');\nsdg.setBtnImg(''btn-end'', ''sup-btn-own-ty'');\nsdg.setBtnImg(''btn-default'', ''sup-btn-own-szmr'');\nsdg.setBtnImg(''btn-changeUse'', ''sup-btn-own-bgyt'');\nsdg.setBtnImg(''btn-suitline'', ''sup-btn-own-sz'');\nsdg.setBtnImg(''btn-checkDepartSet'', ''sup-btn-own-fqqj'');\nsdg.setBtnImg(''btn-proItemSet'', ''sup-btn-own-cdsz'');","isdbcustom":false,"modelCode":"RM_1.0.0_formula_Formula","downloadXls":"/msService/RM/formula/formula/downloadXls","selectFirstRow":false,"renderOver":"let dataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''RM_1.0.0_formula_commonFormulaList_formula_sdg'');\n// 设置点击事件\ndataGrid.setClickEvt((event, formula) => {\n    // 设置默认/取消默认按钮样式\n    let tip = ReactAPI.international.getText(formula.isDafault ? ''RM.custom.randon1578657011034'' : ''RM.custom.randon1578657054218'');\n    $(''#btn-default span'').html(''<i class=\"sup-btn-icon sup-btn-own-szmr\"></i>'' + tip);\n\n    // 当配方为批控配方时，只能使用添加、设置默认、适用产线、设置检验部门按钮\n    let notBatchContral = !formula.batchContral;\n    setBtnStyle(''btn-copy'', notBatchContral);\n    setBtnStyle(''btn-start'', notBatchContral);\n    setBtnStyle(''btn-end'', notBatchContral);\n    setBtnStyle(''btn-copy'', notBatchContral);\n});\nlet data = dataGrid.getDatagridData();\nlet materialId = [];\nlet id;\nfor (let i = 0; i < data.length; i++) {\n    if (data[i].productId != null && data[i].productId.id != null) {\n        materialId.push({ \"materialId\": data[i].productId.id });\n    }\n    else\n        materialId.push({ \"materialId\": -1 });\n}\nif (data.length != 0) {//如果物料编码字段不为空，则发送请求\n    ReactAPI.request({\n        type: \"post\",\n        url: \"/msService/RM/formulaBOM/formulaBomMain/GetMaterialAttributes\",\n        contentType: \"application/json;charset=UTF-8\",\n        data: JSON.stringify(materialId)// 将json数据转化为字符\n    }, function (res) {\n        if (res.success) {\n            for (let i = 0; i < data.length; i++) {//遍历\n                if (res.data[i] != null && res.data[i] == true) {//如果是危化品则为红色\n                    ReactAPI.getComponentAPI(\"SupDataGrid\")\n                        .APIs(\"RM_1.0.0_formula_commonFormulaList_formula_sdg\")\n                        .setDatagridCellAttr(i, \"productId.code\", { style: { color: \"#B30303\" } });\n                }\n                else if (res.data[i] != null && res.data[i] == false) {\n                    ReactAPI.getComponentAPI(\"SupDataGrid\")\n                        .APIs(\"RM_1.0.0_formula_commonFormulaList_formula_sdg\")\n                        .setDatagridCellAttr(i, \"productId.code\", { style: { color: \"#505050\" } });\n                }\n            }\n        }\n    }\n    );\n}","buttons":[{"isSignatureConfig":true,"funcbody":"function copyEvent(event) {\n\tlet dataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''RM_1.0.0_formula_commonFormulaList_formula_sdg'');\n\tlet selecteds = dataGrid.getSelecteds();\n\tif (!selecteds.length) {\n\t\t// 如果没有选节点，则报“请选择一条记录进行操作”\n\t\tReactAPI.showMessage(\"w\", ReactAPI.international.getText(''RM.custom.randon1573717880503''));\n\t\treturn;\n\t}\n\tif (selecteds.length > 1) {\n\t\t// 如果选中了多个节点，则报“只允许对一行进行操作！”\n\t\tReactAPI.showMessage(\"w\", ReactAPI.international.getText(''RM.custom.onceOnlyOneRow''));\n\t\treturn;\n\t}\n\t// 选中行配方\n\tlet formula = selecteds[0];\n\t// 对话框名称\n\tlet dialogName = ''copyFormula'';\n\t// 打开工序编辑对话框\n\tReactAPI.createDialog(dialogName, {\n\t\ttitle: ReactAPI.international.getText(''RM.viewtitle.randon1574822696971''),\n\t\turl: \"/msService/RM/formula/formula/copyFormulaEdit?id=\" + formula.id,\n\t\tsize: 1,\n\t\tisRef: false, // 是否开启参照\n\t\tbuttons: [{\n\t\t\ttext: ReactAPI.international.getText(''Button.text.save''),\n\t\t\ttype: \"primary\",\n\t\t\tonClick: event => {\n\t\t\t\t//保存按钮禁用\n\t\t\t\tsetBtnStyle(''buttons_0'',false);\n\t\t\t\tdebugger;\n\t\t\t\t\tconsole.log(1);\n\t\t\t\tlet inputComponent = event.ReactAPI.getComponentAPI(''Input'');\n\t\t\t\t// 配方编码输入框\n\t\t\t\tlet formulaCodeComponent = inputComponent.APIs(''formula.formualCode'');\n\t\t\t\t// 配方标识输入框\n\t\t\t\tlet formulaNameComponent = inputComponent.APIs(''formula.formulaName'');\n\t\t\t\t// 配方版本输入框\n\t\t\t\tlet formulaEdtionComponent = inputComponent.APIs(''formula.formulaEdtion'');\n\t\t\t\t// 清除上一次校验\n\t\t\t\tformulaNameComponent.setValidateStyle(''success'');\n\t\t\t\tformulaEdtionComponent.setValidateStyle(''success'');\n\t\t\t\t// 数据校验\n\t\t\t\tlet isError = false;\n\t\t\t\tif (!formulaNameComponent.getValue()) {\n\t\t\t\t\tformulaNameComponent.setValidateStyle(''error'', event.ReactAPI.international.getText(''RM.custom.formulaNameNotNull''));\n\t\t\t\t\tisError = true;\n\t\t\t\t\t// 保存按钮可用\n\t\t\t\t\tsetBtnStyle(''buttons_0'',true);\n\t\t\t\t}\n\t\t\t\tif (!formulaEdtionComponent.getValue()) {\n\t\t\t\t\tformulaEdtionComponent.setValidateStyle(''error'', event.ReactAPI.international.getText(''RM.custom.formulaEdtionNotNull''));\n\t\t\t\t\tisError = true;\n\t\t\t\t\t// 保存按钮可用\n\t\t\t\t\tsetBtnStyle(''buttons_0'',true);\n\t\t\t\t}\n\t\t\t\tif (!isError) {\n\t\t\t\t\tconsole.log(1);\n\t\t\t\t\t// 开启遮罩\n\t\t\t\t\tevent.ReactAPI.openLoading(ReactAPI.international.getText(''EditView.notice.processing''));\n\t\t\t\t\tconsole.log(2);\n\t\t\t\t\t// 如果配方编码为空，通过“配方标识_配方版本”回填\n\t\t\t\t\tif (!formulaCodeComponent.getValue()) {\n\t\t\t\t\t\tformulaCodeComponent.setValue(formulaNameComponent.getValue() + \"_\" + formulaEdtionComponent.getValue());\n\t\t\t\t\t}\n\t\t\t\t\t// 请求参数\n\t\t\t\t\tlet data = {\n\t\t\t\t\t\tid: event.ReactAPI.getFormData().id,\n\t\t\t\t\t\tformualCode: formulaCodeComponent.getValue(),\n\t\t\t\t\t\tformulaName: formulaNameComponent.getValue(),\n\t\t\t\t\t\tformulaEdtion: formulaEdtionComponent.getValue()\n\t\t\t\t\t};\n\t\t\t\t\t// 调用复制配方接口\n\t\t\t\t\tReactAPI.request({\n\t\t\t\t\t\ttype: \"post\",\n\t\t\t\t\t\turl: \"/msService/RM/formula/formula/copyFormula\",\n\t\t\t\t\t\tdata: data\n\t\t\t\t\t},\n\t\t\t\t\tres => {\n\t\t\t\t\t\t// 关闭遮罩\n\t\t\t\t\t\tevent.ReactAPI.closeLoading();\n\t\t\t\t\t\t// 保存按钮可用\n\t\t\t\t\t\tsetBtnStyle(''buttons_0'',true);\n\t\t\t\t\t\tif (res.code==200) {\n\t\t\t\t\t\t\tlet data = res.data;\n\t\t\t\t\t\t\tif (data.dealSuccessFlag) {\n\t\t\t\t\t\t\t\t// 关闭窗口\n\t\t\t\t\t\t\t\tReactAPI.destroyDialog(dialogName);\n\t\t\t\t\t\t\t\t// 刷新列表\n\t\t\t\t\t\t\t\tlet currentPage = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formula_commonFormulaList_formula_sdg\").getTablePagination().currentPage;\n\t\t\t\t\t\t\t\tlet pageSize = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formula_commonFormulaList_formula_sdg\").getTablePagination().pageSize;\n\t\t\t\t\t\t\t\tlet url = \"/msService/RM/formula/formula/commonFormulaList-query\";\n\t\t\t\t\t\t\t\tReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formula_commonFormulaList_formula_sdg\").refreshDataByRequst({\n\t\t\t\t\t\t\t\t\ttyp