i < data.length; i++) {\n    if (data[i].productId != null && data[i].productId.id != null) {\n        materialId.push({ \"materialId\": data[i].productId.id });\n    }\n    else\n        materialId.push({ \"materialId\": -1 });\n}\nif (data.length != 0) {//如果物料编码字段不为空，则发送请求\n    ReactAPI.request({\n        type: \"post\",\n        url: \"/msService/RM/formulaBOM/formulaBomMain/GetMaterialAttributes\",\n        contentType: \"application/json;charset=UTF-8\",\n        data: JSON.stringify(materialId)// 将json数据转化为字符\n    }, function (res) {\n        if (res.success) {\n            for (let i = 0; i < data.length; i++) {//遍历\n                if (res.data[i] != null && res.data[i] == true) {//如果是危化品则为红色\n                    ReactAPI.getComponentAPI(\"SupDataGrid\")\n                        .APIs(\"RM_1.0.0_formula_easyFormulaList_formula_sdg\")\n                        .setDatagridCellAttr(i, \"productId.code\", { style: { color: \"#B30303\" } });\n                    // console.log(\"i=\"+i+\",res.data=\"+res.data[i]);\n                }\n                else if (res.data[i] != null && res.data[i] == false) {\n                    ReactAPI.getComponentAPI(\"SupDataGrid\")\n                        .APIs(\"RM_1.0.0_formula_easyFormulaList_formula_sdg\")\n                        .setDatagridCellAttr(i, \"productId.code\", { style: { color: \"#505050\" } });\n                    // console.log(\"i=\"+i+\",res.data=\"+res.data[i]);\n                }\n            }\n        }\n    }\n    );\n}","buttons":[{"isSignatureConfig":true,"funcbody":"function copyEvent(event) {\n    let dataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''RM_1.0.0_formula_easyFormulaList_formula_sdg'');\n    let selecteds = dataGrid.getSelecteds();\n    if (!selecteds.length) {\n        // 如果没有选节点，则报“请选择一条记录进行操作”\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''RM.custom.randon1573717880503''));\n        return;\n    }\n    if (selecteds.length > 1) {\n        // 如果选中了多个节点，则报“只允许对一行进行操作！”\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''RM.custom.onceOnlyOneRow''));\n        return;\n    }\n    // 选中行配方\n    let formula = selecteds[0];\n    // 对话框名称\n    let dialogName = ''copyFormula'';\n    // 打开工序编辑对话框\n    ReactAPI.createDialog(dialogName, {\n        title: ReactAPI.international.getText(''RM.viewtitle.randon1574822696971''),\n        url: \"/msService/RM/formula/formula/copyFormulaEdit?id=\" + formula.id,\n        isRef: false, // 是否开启参照\n        size: 1,\n        buttons: [\n            {\n                text: ReactAPI.international.getText(''Button.text.save''),\n                type: \"primary\",\n                onClick: event => {\n\t\t\t\t\t// 保存按钮禁用\n\t\t\t\t\tevent.setBtnStyle(''buttons_0'',false);\n                    let inputComponent = event.ReactAPI.getComponentAPI(''Input'');\n                    // 配方编码输入框\n                    let formulaCodeComponent = inputComponent.APIs(''formula.formualCode'');\n                    // 配方标识输入框\n                    let formulaNameComponent = inputComponent.APIs(''formula.formulaName'');\n                    // 配方版本输入框\n                    let formulaEdtionComponent = inputComponent.APIs(''formula.formulaEdtion'');\n                    // 清除上一次校验\n                    formulaNameComponent.setValidateStyle(''success'');\n                    formulaEdtionComponent.setValidateStyle(''success'');\n                    // 数据校验\n                    let isError = false;\n                    if (!formulaNameComponent.getValue()) {\n                        formulaNameComponent.setValidateStyle(''error'', event.ReactAPI.international.getText(''RM.custom.formulaNameNotNull''));\n                        isError = true;\n\t\t\t\t\t\t// 保存按钮可用\n\t\t\t\t\t\tevent.setBtnStyle(''buttons_0'',true);\n                    }\n                    if (!formulaEdtionComponent.getValue()) {\n                        formulaEdtionComponent.setValidateStyle(''error'', event.ReactAPI.international.getText(''RM.custom.formulaEdtionNotNull''));\n                        isError = true;// 保存按钮可用\n\t\t\t\t\t\tevent.setBtnStyle(''buttons_0'',true);\n                    }\n                    if (!isError) {\n\t\t\t\t\t\tevent.ReactAPI.openLoading(ReactAPI.international.getText(''EditView.notice.processing''));\n                        // 如果配方编码为空，通过“配方标识_配方版本”回填\n                        if (!formulaCodeComponent.getValue()) {\n                            formulaCodeComponent.setValue(formulaNameComponent.getValue() + \"_\" + formulaEdtionComponent.getValue());\n                        }\n                        // 请求参数\n                        let data = {\n                            id: event.ReactAPI.getFormData().id,\n                            formualCode: formulaCodeComponent.getValue(),\n                            formulaName: formulaNameComponent.getValue(),\n                            formulaEdtion: formulaEdtionComponent.getValue()\n                        };\n                        // 调用复制配方接口\n                        event.ReactAPI.request(\n                            {\n                                type: \"post\",\n                                url: \"/msService/RM/formula/formula/copyFormula\",\n                                data: data\n                            },\n                            res => {\n\t\t\t\t\t\t\t\tevent.ReactAPI.closeLoading();\n\t\t\t\t\t\t\t\t// 保存按钮可用\n\t\t\t\t\t\t\t\tevent.setBtnStyle(''buttons_0'',true);\n                                if (res.code == 200) {\n                                    let data = res.data;\n                                    if (data.dealSuccessFlag) {\n                                        // 关闭窗口\n                                        ReactAPI.destroyDialog(dialogName);\n                                        // 刷新列表\n                                        let currentPage = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formula_easyFormulaList_formula_sdg\").getTablePagination().currentPage;\n                                        let pageSize = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formula_easyFormulaList_formula_sdg\").getTablePagination().pageSize;\n                                        let url = \"/msService/RM/formula/formula/easyFormulaList-query\";\n                                        ReactAPI.getComponentAPI(\"SupDataGrid\")\n                                            .APIs(\"RM_1.0.0_formula_easyFormulaList_formula_sdg\")\n                                            .refreshDataByRequst({\n                                                type: \"POST\",\n                                                url: url,\n                                                param: {\n                                                    classifyCodes: \",\",\n                                                    customCondition: {},\n                                                    pageNo: currentPage,\n                                                    paging: true,\n                                                    pageSize: pageSize,\n                                                },\n                                            });\n                                        // 处理成功！\n                                        ReactAPI.showMessage(\"s\", ReactAPI.international.getText(''RM.custom.dealSuccess''));\n                                    } else {\n                                        ReactAPI.showMessage(\"f\", data.errorMessage);\n                                    }\n                                } else {\n                                    ReactAPI.showMessage(\"f\", res.message);\n                                }\n                            }\n                        );\n                    }\n                }\n            },\n            {\n                text: ReactAPI.international.getText(''Button.text.cancel''),\n                onClick: event => {\n                    ReactAPI.destroyDialog(dialogName);\n                }\n            }\n        ]\n    });\n}","funcname":"onclick=''copyEvent(event)''","buttonstyle":"add","iscustomfunc":false,"useInMore":false,"isPublished":false,"ispermission":false,"cellCode":"cell_1574735843773_2328","buttonoperationcode":"easyFormulaList_copy_add_RM_1.0.0_formula_easyFormulaList","isHide":false,"showname":"复制","ecEnv":"product","pc":"__pc__=Uk1fMS4wLjBfZm9ybXVsYV9lYXN5Rm9ybXVsYUxpc3Rfc2VsZnw_","regionType":"BUTTON","iscallback":false,"modelCode":"RM_1.0.0_formula_Formula","namekey":"RM.buttonPropertyshowName.randon1574735855178.flag","funcbody_es5":"function copyEvent(event) {\n    var dataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''RM_1.0.0_formula_easyFormulaList_formula_sdg'');\n    var selecteds = dataGrid.getSelecteds();\n    if (!selecteds.length) {\n        // 如果没有选节点，则报“请选择一条记录进行操作”\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''RM.custom.randon1573717880503''));\n        return;\n    }\n    if (selecteds.length > 1) {\n        // 如果选中了多个节点，则报“只允许对一行进行操作！”\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''RM.custom.onceOnlyOneRow''));\n        return;\n    }\n    // 选中行配方\n    var formula = selecteds[0];\n    // 对话框名称\n    var dialogName = ''copyFormula'';\n    // 打开工序编辑对话框\n    ReactAPI.createDialog(dialogName, {\n        title: ReactAPI.international.getText(''RM.viewtitle.randon1574822696971''),\n        url: \"/msService/RM/formula/formula/copyFormulaEdit?id=\" + formula.id,\n        isRef: false, // 是否开启参照\n        size: 1,\n        buttons: [{\n            text: ReactAPI.international.getText(''Button.text.save''),\n            type: \"primary\",\n            onClick: function onClick(event) {\n                // 保存按钮禁用\n                event.setBtnStyle(''buttons_0'', false);\n                var inputComponent = event.ReactAPI.getComponentAPI(''Input'');\n                // 配方编码输入框\n                var formulaCodeComponent = inputComponent.APIs(''formula.formualCode'');\n                // 配方标识输入框\n                var formulaNameComponent = inputComponent.APIs(''formula.formulaName'');\n                // 配方版本输入框\n                var formulaEdtionComponent = inputComponent.APIs(''formula.formulaEdtion'');\n                // 清除上一次校验\n                formulaNameComponent.setValidateStyle(''success'');\n                formulaEdtionComponent.setValidateStyle(''success'');\n                // 数据校验\n                var isError = false;\n                if (!formulaNameComponent.getValue()) {\n                    formulaNameComponent.setValidateStyle(''error'', event.ReactAPI.international.getText(''RM.custom.formulaNameNotNull''));\n                    isError = true;\n                    // 保存按钮可用\n                    event.setBtnStyle(''buttons_0'', true);\n                }\n                if (!formulaEdtionComponent.getValue()) {\n                    formulaEdtionComponent.setValidateStyle(''error'', event.ReactAPI.international.getText(''RM.custom.formulaEdtionNotNull''));\n                    isError = true; // 保存按钮可用\n                    event.setBtnStyle(''buttons_0'', true);\n                }\n                if (!isError) {\n                    event.ReactAPI.openLoading(ReactAPI.international.getText(''EditView.notice.processing''));\n                    // 如果配方编码为空，通过“配方标识_配方版本”回填\n                    if (!formulaCodeComponent.getValue()) {\n                        formulaCodeComponent.setValue(formulaNameComponent.getValue() + \"_\" + formulaEdtionComponent.getValue());\n                    }\n                    // 请求参数\n                    var data = {\n                        id: event.ReactAPI.getFormData().id,\n                        formualCode: formulaCodeComponent.getValue(),\n                        formulaName: formulaNameComponent.getValue(),\n                        formulaEdtion: formulaEdtionComponent.getValue()\n                    };\n                    // 调用复制配方接口\n                    event.ReactAPI.request({\n                        type: \"post\",\n                        url: \"/msService/RM/formula/formula/copyFormula\",\n                        data: data\n                    }, function (res) {\n                        event.ReactAPI.closeLoading();\n                        // 保存按钮可用\n                        event.setBtnStyle(''buttons_0'', true);\n                        if (res.code == 200) {\n                            var _data = res.data;\n                            if (_data.dealSuccessFlag) {\n                                // 关闭窗口\n                                ReactAPI.destroyDialog(dialogName);\n                                // 刷新列表\n                                var currentPage = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formula_easyFormulaList_formula_sdg\").getTablePagination().currentPage;\n                                var pageSize = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formula_easyFormulaList_formula_sdg\").getTablePagination().pageSize;\n                                var url = \"/msService/RM/formula/formula/easyFormulaList-query\";\n                                ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formula_easyFormulaList_formula_sdg\").refreshDataByRequst({\n                                    type: \"POST\",\n                                    url: url,\n                                    param: {\n                                        classifyCodes: \",\",\n                                        customCondition: {},\n                                        pageNo: currentPage,\n                                        paging: true,\n                                        pageSize: pageSize\n                                    }\n                                });\n                                // 处理成功！\n                                ReactAPI.showMessage(\"s\", ReactAPI.international.getText(''RM.custom.dealSuccess''));\n                            } else {\n                                ReactAPI.showMessage(\"f\", _data.errorMessage);\n                            }\n                        } else {\n                            ReactAPI.showMessage(\"f\", res.message);\n                        }\n                    });\n                }\n            }\n        }, {\n            text: ReactAPI.international.getText(''Button.text.cancel''),\n            onClick: function onClick(event) {\n                ReactAPI.destroyDialog(dialogName);\n            }\n        }]\n    });\n}","id":"copy","operatetype":"CUSTOM","isconfirm":false,"CODE":"easyFormulaList_copy_add_RM_1.0.0_formula_easyFormulaList","NAME":"复制","ICONCLS":"cui-btn-add","USEINMORE":false,"SEPARATENUM":"0"},{"isSignatureConfig":true,"funcbody":"function startEvent(event) {\n    console.log(\"start\");\n    var dataGrid = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formula_easyFormulaList_formula_sdg\");\n    var selecteds = dataGrid.getSelecteds();\n    if (selecteds.length == 0) {\n        // 如果没有选节点，则报“请选择一条记录进行操作”\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''RM.custom.randon1573717880503''));\n        return false;\n    }\n    var ids = '''';\n    for (var i = 0; i < selecteds.length; i++) {\n        var row = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formula_easyFormulaList_formula_sdg\").getSelecteds()[i];\n        var status = row.status\n        if (status == 88) {\n            ReactAPI.showMessage(\"f\", ReactAPI.international.getText(''RM.custom.randon1574755044078''));\n            return false;\n        } else if (row.state && row.state.id == ''RM_state/enabled'') {\n            ReactAPI.showMessage(\"f\", ReactAPI.international.getText(''RM.custom.randon1574759597334''));\n            return false;\n        } else {\n            ids += '','' + row.id;\n        }\n    }\n    if (ids != '''') {\n        ids = ids.substr(1);\n    }\n    $.ajax({\n        url: \"/msService/RM/formula/formula/updateFomulaState\",\n        type: ''post'',\n        async: false,\n        data: { state: \"RM_state/enabled\", ids: ids },\n        success: function (res) {\n            //启用成功\n            ReactAPI.showMessage(\"s\", ReactAPI.international.getText(\"foundation.language.enable.success\"));\n            let currentPage = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formula_easyFormulaList_formula_sdg\").getTablePagination().currentPage;\n            let pageSize = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formula_easyFormulaList_formula_sdg\").getTablePagination().pageSize;\n            let url = \"/msService/RM/formula/formula/easyFormulaList-query\";\n            ReactAPI.getComponentAPI(\"SupDataGrid\")\n                .APIs(\"RM_1.0.0_formula_easyFormulaList_formula_sdg\")\n                .refreshDataByRequst({\n                    type: \"POST\",\n                    url: url,\n                    param: {\n                        classifyCodes: \",\",\n                        customCondition: {},\n                        pageNo: currentPage,\n                        paging: true,\n                        pageSize: pageSize,\n                    },\n                });\n            return;\n        }\n    });\n}","funcname":"onclick=''startEvent(event)''","buttonstyle":"add","iscustomfunc":false,"useInMore":false,"isPublished":false,"ispermission":false,"cellCode":"cell_1574735895003_2167","buttonoperationcode":"easyFormulaList_start_add_RM_1.0.0_formula_easyFormulaList","isHide":false,"showname":"启用","ecEnv":"product","pc":"__pc__=Uk1fMS4wLjBfZm9ybXVsYV9lYXN5Rm9ybXVsYUxpc3Rfc2VsZnw_","regionType":"BUTTON","iscallback":false,"modelCode":"RM_1.0.0_formula_Formula","namekey":"RM.buttonPropertyshowName.randon1574735902163.flag","funcbody_es5":"function startEvent(event) {\n    console.log(\"start\");\n    var dataGrid = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.