';\n    for (var i = 0; i < selecteds.length; i++) {\n        var row = dataGrid.getSelecteds()[i];\n        var status = row.status\n        if (status == 88) {\n            ReactAPI.showMessage(\"f\", ReactAPI.international.getText(''RM.custom.randon1624507911528''));\n            return false;\n        } else if (row.state == null ||　(row.state != null && row.state.id == ''RM_state/notEnabled'') ) {\n\t\t\t//配方未启用，不能停用！\n\t\t\tReactAPI.showMessage(\"f\", ReactAPI.international.getText(''RM.custom.randon1624932897664''));\n            return false; \n\t\t} else if (!row.state || row.state.id == ''RM_state/disabled'') {\n\t\t\t//存在单据已停用，不能重复停用！\n            ReactAPI.showMessage(\"f\", ReactAPI.international.getText(''RM.custom.randon1574759822999''));\n            return false;\n        }else {\n            ids += '','' + row.id;\n        }\n    }\n    if (ids != '''') {\n        ids = ids.substr(1);\n    }\n    $.ajax({\n        url: \"/msService/RM/formula/formula/updateFomulaState\",\n        type: ''post'',\n        async: false,\n        data: {\n            state: \"RM_state/disabled\",\n            ids: ids\n        },\n        success: function (res) {\n            //停用成功\n            ReactAPI.showMessage(\"s\", ReactAPI.international.getText(\"foundation.language.disable.success\"));\n\n            // 查询刷新PT\n            let currentPage = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formula_craftFormulaList_formula_sdg\").getTablePagination().currentPage;\n            let pageSize = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formula_craftFormulaList_formula_sdg\").getTablePagination().pageSize;\n            let url = \"/msService/RM/formula/formula/craftFormulaList-query\";\n            ReactAPI.getComponentAPI(\"SupDataGrid\")\n                .APIs(\"RM_1.0.0_formula_craftFormulaList_formula_sdg\")\n                .refreshDataByRequst({\n                    type: \"POST\",\n                    url: url,\n                    param: {\n                        classifyCodes: \",\",\n                        customCondition: {},\n                        pageNo: currentPage,\n                        paging: true,\n                        pageSize: pageSize,\n                    },\n                });\n            return;\n        }\n    });\n}","funcbody_es5":"function endEvent(event) {\n    var dataGrid = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formula_craftFormulaList_formula_sdg\");\n    var selecteds = dataGrid.getSelecteds();\n    if (selecteds.length == 0) {\n        // 如果没有选节点，则报“请选择一条记录进行操作”\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''RM.custom.randon1573717880503''));\n        return false;\n    }\n\n    var ids = '''';\n    for (var i = 0; i < selecteds.length; i++) {\n        var row = dataGrid.getSelecteds()[i];\n        var status = row.status;\n        if (status == 88) {\n            ReactAPI.showMessage(\"f\", ReactAPI.international.getText(''RM.custom.randon1624507911528''));\n            return false;\n        } else if (row.state == null || row.state != null && row.state.id == ''RM_state/notEnabled'') {\n            //配方未启用，不能停用！\n            ReactAPI.showMessage(\"f\", ReactAPI.international.getText(''RM.custom.randon1624932897664''));\n            return false;\n        } else if (!row.state || row.state.id == ''RM_state/disabled'') {\n            //存在单据已停用，不能重复停用！\n            ReactAPI.showMessage(\"f\", ReactAPI.international.getText(''RM.custom.randon1574759822999''));\n            return false;\n        } else {\n            ids += '','' + row.id;\n        }\n    }\n    if (ids != '''') {\n        ids = ids.substr(1);\n    }\n    $.ajax({\n        url: \"/msService/RM/formula/formula/updateFomulaState\",\n        type: ''post'',\n        async: false,\n        data: {\n            state: \"RM_state/disabled\",\n            ids: ids\n        },\n        success: function success(res) {\n            //停用成功\n            ReactA