uccess(res) {\n            //停用成功\n            ReactAPI.showMessage(\"s\", ReactAPI.international.getText(\"foundation.language.disable.success\"));\n\n            // 查询刷新PT\n            var currentPage = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formula_craftFormulaList_formula_sdg\").getTablePagination().currentPage;\n            var pageSize = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formula_craftFormulaList_formula_sdg\").getTablePagination().pageSize;\n            var url = \"/msService/RM/formula/formula/craftFormulaList-query\";\n            ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formula_craftFormulaList_formula_sdg\").refreshDataByRequst({\n                type: \"POST\",\n                url: url,\n                param: {\n                    classifyCodes: \",\",\n                    customCondition: {},\n                    pageNo: currentPage,\n                    paging: true,\n                    pageSize: pageSize\n                }\n            });\n            return;\n        }\n    });\n}","iscallback":false,"iscustomfunc":false,"useInMore":false,"isconfirm":false,"isSignatureConfig":true,"cellCode":"cell_1628127233860_3","ecEnv":"product","regionType":"BUTTON","i18nKey":"RM.buttonPropertyshowName.randon1573641248453.flag","name":"停用","operateType":"CUSTOM","onclick":"endEvent(event)","ONCLICK":"endEvent(event)","CODE":"craftFormulaList_end_add_RM_1.0.0_formula_craftFormulaList","NAME":"停用","ICONCLS":"cui-btn-add","USEINMORE":false,"SEPARATENUM":"0"},{"id":"default","showname":"设置默认","namekey":"设置默认","buttonstyle":"add","operatetype":"CUSTOM","isHide":false,"ispermission":false,"isPublished":false,"buttonoperationcode":"craftFormulaList_default_add_RM_1.0.0_formula_craftFormulaList","funcname":"onclick=''defaultEvent(event)''","funcbody":"function defaultEvent(event) {\n    let dataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''RM_1.0.0_formula_craftFormulaList_formula_sdg'');\n    let selecteds = dataGrid.getSelecteds();\n    if (!selecteds.length) {\n        // 如果没有选节点，则报“请选择一条记录进行操作”\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''RM.custom.randon1573717880503''));\n        return;\n    }\n    if (selecteds.length > 1) {\n        // 如果选中了多个节点，则报“只允许对一行进行操作！”\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''RM.custom.onceOnlyOneRow''));\n        return;\n    }\n    // 选中行\n    let formula = selecteds[0];\n    if (formula.state.id !== \"RM_state/enabled\") {\n        // 如果配方不是启用状态\n        ReactAPI.showMessage(\"f\", ReactAPI.international.getText(''RM.custom.random1643017683156''));\n        return;\n    }\n    if (formula.status == 99) {\n        // 设置配方为默认配方\n        ReactAPI.request(\n            {\n                type: \"post\",\n                url: \"/msService/RM/formula/formula/setFormulaDefault/\" + formula.id + \"?isDefault=\" + !formula.isDafault,\n            },\n            res => {\n                if (res.code == 200) {\n                    let data = res.data;\n                    if (data.dealSuccessFlag) {\n                        // 处理成功！\n                        ReactAPI.showMessage(\"s\", ReactAPI.international.getText(''RM.custom.dealSuccess''));\n                        // 刷新列表\n                        let currentPage = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formula_craftFormulaList_formula_sdg\").getTablePagination().currentPage;\n                        let pageSize = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formula_craftFormulaList_formula_sdg\").getTablePagination().pageSize;\n                        let url = \"/msService/RM/formula/formula/craftFormulaList-query\";\n                        ReactAPI.getComponentAPI(\"SupDataGrid\")\n                            .APIs(\"RM_1.0.0_formula_craftFormulaList_formula_sdg\")\n                            .refreshDataByRequst({\n                                type: \"POST\",\n                                url: url,\n                                param: {\n                                    classifyCodes: \",\",\n                                    customCondition: {},\n                                    pageNo: currentPage,\n                                    paging: true,\n                                    pageSize: pageSize,\n                                },\n                            });\n                    } else {\n                        ReactAPI.showMessage(\"f\", data.errorMessage);\n                    }\n                } else {\n                    ReactAPI.showMessage(\"f\", res.message);\n                }\n            }\n        );\n    } else {\n        //配方生效后才可以设置默认\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''RM.custom.randon1577945423614''));\n        return;\n    }\n\n}","funcbody_es5":"function defaultEvent(event) {\n    var dataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''RM_1.0.0_formula_craftFormulaList_formula_sdg'');\n    var selecteds = dataGrid.getSelecteds();\n    if (!selecteds.length) {\n        // 如果没有选节点，则报“请选择一条记录进行操作”\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''RM.custom.randon1573717880503''));\n        return;\n    }\n    if (selecteds.length > 1) {\n        // 如果选中了多个节点，则报“只允许对一行进行操作！”\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''RM.custom.onceOnlyOneRow''));\n        return;\n    }\n    // 选中行\n    var formula = selecteds[0];\n    if (formula.state.id !== \"RM_state/enabled\") {\n        // 如果配方不是启用状态\n        ReactAPI.showMessage(\"f\", ReactAPI.international.getText(''RM.custom.random1643017683156''));\n        return;\n    }\n    if (formula.status == 99) {\n        // 设置配方为默认配方\n        ReactAPI.request({\n            type: \"post\",\n            url: \"/msService/RM/formula/formula/setFormulaDefault/\" + formula.id + \"?isDefault=\" + !formula.isDafault\n        }, function (res) {\n            if (res.code == 200) {\n                var data = res.data;\n                if (data.dealSuccessFlag) {\n                    // 处理成功！\n                    ReactAPI.showMessage(\"s\", ReactAPI.international.getText(''RM.custom.dealSuccess''));\n                    // 刷新列表\n                    var currentPage = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formula_craftFormulaList_formula_sdg\").getTablePagination().currentPage;\n                    var pageSize = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formula_craftFormulaList_formula_sdg\").getTablePagination().pageSize;\n                    var url = \"/msService/RM/formula/formula/craftFormulaList-query\";\n                    ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formula_craftFormulaList_formula_sdg\").refreshDataByRequst({\n                        type: \"POST\",\n                        url: url,\n                        param: {\n                            classifyCodes: \",\",\n                            customCondition: {},\n                            pageNo: currentPage,\n                            paging: true,\n                            pageSize: pageSize\n                        }\n                    });\n                } else {\n                    ReactAPI.showMessage(\"f\", data.errorMessage);\n                }\n            } else {\n                ReactAPI.showMessage(\"f\", res.message);\n            }\n        });\n    } else {\n        //配方生效后才可以设置默认\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''RM.custom.randon1577945423614''));\n        return;\n    }\n}","iscallback":false,"iscustomfunc":false,"useInMore":false,"isconfirm":false,"isSignatureConfig":true,"cellCode":"cell_1628127233860_4","ecEnv":"product","regionType":"BUTTON","i18nKey":"RM.buttonPropertyshowName.randon1573641296631.flag","name":"设置默认","operateType":"CUSTOM","onclick":"defaultEvent(event)","ONCLICK":"defaultEvent(event)","CODE":"craftFormulaList_default_add_RM_1.0.0_